  r=read(p);assert r['exit_code']==0 and r['child_waited'] and not r['timed_out'];count+=1
  for stream in ('stdout','stderr'):assert sha(o/(p.name[:-13]+'.'+stream))==r[stream+'_sha256']
 assert all(sha(root/n)==h for n,h in m['source_sha256'].items())
