 if stage=='build':
  assert c['qmods']==391 and '-O3 -DNDEBUG' in c['flags'];assert 'ENABLE_ALLOC_TRACKING:BOOL=OFF' in (root/'build/CMakeCache.txt').read_text();assert all(sha(root/'build'/n)==h==sha(Path(c['after_runtime'])/n) for n,h in c['artifacts'].items());result['qmods']=391
