  expected=18 if stage=='tests' else 7;assert len(c['rows'])==expected;cases=assertions=0
  for row in c['rows']:
   name=row['name'] if stage=='tests' else row['test'];raw=(o/(name+'.stdout')).read_text()+(o/(name+'.stderr')).read_text();assert all(x not in raw for x in ('SKIP','FAILURE:','loading source module'));summaries=re.findall(r'^Ran (\d+) test cases?, (\d+) succeeded \((\d+) assertions?\)$',raw,re.M);assert len(summaries)==1 and summaries[0][0]==summaries[0][1];assert sha(o/(name+'.process.json'))==row['process_sha256'];cases+=int(summaries[0][0]);assertions+=int(summaries[0][2])
  result.update(fixtures=expected,cases=cases,assertions=assertions)
